excels.excel:

EXPORT WITH SHEET="研发项目绩效考核评分表", HEADER=true,
    MAPPING={"a":"项目名称","b":"负责人","c":"进度达成","d":"质量得分","e":"成本控制得分","f":"综合得分","g":"评级"},
    FORMAT={"c":"#,##0.0","d":"#,##0.0","e":"#,##0.0","f":"#,##0.00"},
    FORMULAS={
        F2:'C2*0.4+D2*0.35+E2*0.25',F3:'C3*0.4+D3*0.35+E3*0.25',
        F4:'C4*0.4+D4*0.35+E4*0.25',F5:'C5*0.4+D5*0.35+E5*0.25',
        F6:'C6*0.4+D6*0.35+E6*0.25',
        F7:'AVERAGE(F2:F6)'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        F4:{color:red,bold:true}
    }
